import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.CRfKVJQk.js";const p=JSON.parse(`{"title":"02 · JS layer","description":"TurboModuleRegistry.get('LiquidGlassModule') returns null when native code isn't compiled in (Expo Go, Jest, or an app that wasn't rebuilt). That single…","frontmatter":{"description":"TurboModuleRegistry.get('LiquidGlassModule') returns null when native code isn't compiled in (Expo Go, Jest, or an app that wasn't rebuilt). That single…","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/02-js-layer"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/02-js-layer"}],["meta",{"property":"og:title","content":"02 · JS layer · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"TurboModuleRegistry.get('LiquidGlassModule') returns null when native code isn't compiled in (Expo Go, Jest, or an app that wasn't rebuilt). That single…"}],["meta",{"name":"twitter:title","content":"02 · JS layer · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"TurboModuleRegistry.get('LiquidGlassModule') returns null when native code isn't compiled in (Expo Go, Jest, or an app that wasn't rebuilt). That single…"}]]},"headers":[],"relativePath":"architecture/02-js-layer.md","filePath":"architecture/02-js-layer.md"}`),r={name:"architecture/02-js-layer.md"};function s(i,e,n,l,c,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_02-·-js-layer" tabindex="-1">02 · JS layer <a class="header-anchor" href="#_02-·-js-layer" aria-label="Permalink to &quot;02 · JS layer&quot;">​</a></h1><h2 id="files-and-their-single-job" tabindex="-1">Files and their single job <a class="header-anchor" href="#files-and-their-single-job" aria-label="Permalink to &quot;Files and their single job&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Job</th></tr></thead><tbody><tr><td><code>specs/*.ts</code></td><td>Codegen contract. Flat props only.</td></tr><tr><td><code>native/nativeBridge.ts</code></td><td>Only importer of specs. Exposes <code>NativeGlassView</code>, <code>NativeBackdrop</code>, <code>nativeModule</code>, <code>isNativeAvailable</code>.</td></tr><tr><td><code>native/nativeBridge.web.ts</code></td><td>Web: everything null, so fallbacks are used.</td></tr><tr><td><code>materials/presets.ts</code></td><td>The four built-in materials.</td></tr><tr><td><code>materials/resolveMaterial.ts</code></td><td>preset → theme override → prop → intensity → clamp. Pure.</td></tr><tr><td><code>theme/*</code></td><td>Provider (nestable), <code>mergeTheme</code>, <code>useGlassTheme</code> (adds the resolved colour scheme).</td></tr><tr><td><code>quality/normalizeQuality.ts</code></td><td>Validates the string. &quot;auto&quot; is decided natively.</td></tr><tr><td><code>components/LiquidGlassView/useResolvedGlass.ts</code></td><td>Joins theme + material + props + accessibility into final values.</td></tr><tr><td><code>components/LiquidGlassView/FallbackGlass.tsx</code></td><td>Pure JS glass (web: CSS <code>backdrop-filter</code>; native-missing: tinted view).</td></tr><tr><td><code>utils/splitGlassProps.ts</code></td><td>Separates &quot;how glass looks&quot; props from everything else (used by Button/Card).</td></tr></tbody></table><h2 id="how-is-native-linked-is-decided" tabindex="-1">How &quot;is native linked?&quot; is decided <a class="header-anchor" href="#how-is-native-linked-is-decided" aria-label="Permalink to &quot;How &quot;is native linked?&quot; is decided&quot;">​</a></h2><p><code>TurboModuleRegistry.get(&#39;LiquidGlassModule&#39;)</code> returns <code>null</code> when native code isn&#39;t compiled in (Expo Go, Jest, or an app that wasn&#39;t rebuilt). That single check switches every component to its JS fallback and logs one dev warning. Rendering a native component that isn&#39;t registered would crash, so this check happens first.</p><h2 id="precedence-last-wins" tabindex="-1">Precedence (last wins) <a class="header-anchor" href="#precedence-last-wins" aria-label="Permalink to &quot;Precedence (last wins)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Source</th><th>Example</th></tr></thead><tbody><tr><td>1</td><td>Built-in preset</td><td><code>regular.blur = 20</code></td></tr><tr><td>2</td><td>Theme override</td><td><code>&lt;GlassThemeProvider theme={{ materials: { regular: { blur: 24 } } }}&gt;</code></td></tr><tr><td>3</td><td>Component prop</td><td><code>&lt;LiquidGlassView blur={12}&gt;</code></td></tr><tr><td>4</td><td><code>intensity</code> multiplier</td><td><code>intensity={0.5}</code> → blur, refraction, distortion, illumination, RGB split × 0.5</td></tr><tr><td>5</td><td>Clamp</td><td>blur 0–100 dp, strengths 0–1, border 0–8 dp, edge 0–64 dp</td></tr></tbody></table><p><code>tintOpacity</code> is <strong>not</strong> scaled by intensity. Intensity controls the effect, not the colour.</p><h2 id="corner-radius" tabindex="-1">Corner radius <a class="header-anchor" href="#corner-radius" aria-label="Permalink to &quot;Corner radius&quot;">​</a></h2><p><code>cornerRadius</code> prop → <code>style.borderRadius</code> (numbers only) → theme default (24). Native clamps it to half the shortest side, so <code>cornerRadius={999}</code> gives a pill.</p><h2 id="composed-components" tabindex="-1">Composed components <a class="header-anchor" href="#composed-components" aria-label="Permalink to &quot;Composed components&quot;">​</a></h2><p><code>LiquidGlassButton</code> and <code>LiquidGlassCard</code> never re-implement glass. They render <code>LiquidGlassView</code> and forward glass props via <code>splitGlassProps</code>. This is the &quot;Material separate from Component&quot; rule.</p><h3 id="button-press-feedback-who-animates" tabindex="-1">Button press feedback: who animates? <a class="header-anchor" href="#button-press-feedback-who-animates" aria-label="Permalink to &quot;Button press feedback: who animates?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Squish</th><th>Highlight</th></tr></thead><tbody><tr><td>Android (native linked)</td><td>native (canvas scale + spring)</td><td>native</td></tr><tr><td>iOS 26+</td><td>JS <code>Animated</code> spring (0.96) + system response when the touch lands on the glass</td><td>system</td></tr><tr><td>iOS 15–25, fallback</td><td>JS <code>Animated</code> spring (0.96)</td><td>sheen boost via <code>pressed</code></td></tr><tr><td>Reduce motion on</td><td>none</td><td>yes</td></tr></tbody></table>',14)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
